import sys

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    n = int(next(iterator))
    m = int(next(iterator))

    adj = [[False] * (n + 1) for _ in range(n + 1)]

    for _ in range(m):
        u = int(next(iterator))
        v = int(next(iterator))
        adj[u][v] = True

    count = 0

    for a in range(1, n + 1):
        for c in range(1, n + 1):
            if a == c:
                continue

            paths = 0
            for k in range(1, n + 1):
                if k != a and k != c:
                    if adj[a][k] and adj[k][c]:
                        paths += 1

            if paths >= 2:
                count += paths * (paths - 1) // 2

    print(count)

if __name__ == "__main__":
    main()
